generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName ?avgProgress WHERE {
  {
    SELECT ?inv (AVG(xsd:decimal(?progress)) AS ?avgProgress) WHERE {
      ?inv a wm:Investor .
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?progress .
    }
    GROUP BY ?inv
    HAVING (AVG(xsd:decimal(?progress)) < 30)
  }
  {
    SELECT ?inv WHERE {
      ?inv a wm:Investor .
      ?inv wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?riskScore .
      FILTER(xsd:decimal(?riskScore) > 70)
    }
  }
  {
    SELECT DISTINCT ?inv WHERE {
      ?inv a wm:Investor .
      ?inv wm:hasHolding ?hold .
      ?hold wm:returnsPct ?ret .
      FILTER(xsd:decimal(?ret) < 0)
    }
  }
  {
    SELECT ?inv WHERE {
      ?inv a wm:Investor .
      ?inv wm:hasSectorAllocation ?alloc .
      ?alloc wm:allocationPct ?allocPct .
      FILTER(xsd:decimal(?allocPct) > 30)
    }
  }
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }
}

